  async function renderSeriesBatch(){$('studio-workspace').innerHTML='<div class="studio-grid studio-two"><section class="studio-main studio-span">'+heading('SERIES EDITION','让一整个系列，保持同一种气质。','选择需要更新的作品，统一品牌位置与层级，保留每期自己的主题。')+'<div id="batch-projects" class="studio-list"></div><div class="studio-actions"><button id="batch-covers" class="studio-button">批量重绘封面</button><button id="batch-copy" class="studio-button">批量生成文案</button></div><div id="studio-result"></div></section></div>';mountCoverTabs();const projectId=currentProject(),seriesId=ui.data.projectConfig?.seriesId;if(!seriesId){$('batch-projects').append(node('div','studio-note','先在工程设置中将当前作品加入一个系列。'));return;}try{const result=await action('series.overview',{seriesId});if(projectId!==currentProject()||ui.section!=='covers'||ui.coverPanel!=='batch')return;const projects=list(result.projects||result.items);for(const project of projects){const row=node('label','batch-project-row'),check=node('input');check.type='checkbox';check.dataset.batchProject=project.id;check.checked=project.id===projectId;row.append(check);if(project.thumbnailUrl){const img=node('img');img.src=safeUrl(project.thumbnailUrl);img.loading='lazy';row.append(img);}row.append(node('span','',project.displayName||project.title||project.name));$('batch-projects').append(row);}for(const kind of ['covers','copy'])bindAction(`batch-${kind}`,async()=>{const projectIds=[...document.querySelectorAll('[data-batch-project]:checked')].map(n=>n.dataset.batchProject);if(!projectIds.length)throw new Error('至少选择一个作品。');const result=await action('workflow.start',{kind:`batch-${kind}`,seriesId,projectIds,prompt:kind==='covers'?'遵守系列封面规范，结合每期最突出的真实画面重绘封面。':'结合各期成片生成四个平台发布文案，保持系列语气且避免重复。'});watchWorkflow(result.workflowId||result.workflow?.id,$('studio-result'));});}catch(error){if($('batch-projects'))$('batch-projects').append(node('div','studio-note',error.message));}}
  function canvasPoint(event){const r=$('cover-canvas').getBoundingClientRect();return{x:(event.clientX-r.left)/r.width,y:(event.clientY-r.top)/r.height};}
