  async function reopenCover(id){const record=await action('cover.load',{id});ui.cover=structuredClone(defaultCover);ui.ratioLayouts={};importCoverTemplate({layout:record.layout||{}});ui.cover.ratio=ratios[record.ratio]?record.ratio:'16:9';ui.cover.savedId=id;ui.cover.initialized=true;ui.cover.seriesApplied=true;if(record.editorProject?.type==='minipaint'){ui.cover.editorJSON=typeof record.editorProject.json==='string'?record.editorProject.json:JSON.stringify(record.editorProject.json);await wb.refresh();const media=wb.getMedia().find(m=>m.relativePath===record.path);if(media)ui.cover.flattenedImage=safeUrl(media.url);}saveStudioDraft();renderCovers();window.dispatchEvent(new Event('studio:cover-restored'));wb.toast(record.editorProject?'封面与独立图层已恢复，点击图层精修继续编辑':'封面文字与布局已恢复');}
  function changeRatio(ratio){if(ui.cover.ratio===ratio)return;if(ui.cover.flattenedImage||ui.cover.editorJSON)ui.ratioEditors[ui.cover.ratio]={flattenedImage:ui.cover.flattenedImage,editorJSON:ui.cover.editorJSON};else delete ui.ratioEditors[ui.cover.ratio];delete ui.cover.flattenedImage;delete ui.cover.editorJSON;Object.assign(ui.cover,ui.ratioEditors[ratio]||{});ui.ratioLayouts[ui.cover.ratio]={positions:structuredClone(ui.cover.positions),layers:structuredClone(ui.cover.layers),backgroundImage:ui.cover.backgroundImage,backgroundOverlay:ui.cover.backgroundOverlay};const saved=ui.ratioLayouts[ratio];ui.cover.ratio=ratio;if(ui.cover.legacyPreview){const ratioToken=ratio.replace(':','x'),media=wb.getMedia().find(m=>m.kind==='image'&&((m.ratio===ratio)||m.name.includes(ratioToken)));if(media){ui.cover.flattenedImage=safeUrl(media.url);ui.cover.sourceMedia=media;}}if(saved){ui.cover.positions=structuredClone(saved.positions);ui.cover.layers=structuredClone(saved.layers);ui.cover.backgroundImage=saved.backgroundImage;ui.cover.backgroundOverlay=saved.backgroundOverlay;}else{delete ui.cover.backgroundImage;delete ui.cover.backgroundOverlay;const portrait=['3:4','9:16'].includes(ratio);ui.cover.positions={title:{x:.08,y:portrait?.2:.27},subtitle:{x:.08,y:portrait?.43:.78},logo:{x:.055,y:.05}};ui.cover.layers=ui.cover.layers.map((l,i)=>({...l,x:portrait?.5:.68,y:portrait?.68:.6,scale:portrait?.72:.6}));}}
